  DATA "the_geom FROM (SELECT gid, the_geom, grado_marginacion FROM marco_geoestadistico.mun_ver) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Texto Grado de marginacion por municipio"
    "wms_enable_request" "*"
